"123\" width=\"7\" height=\"9\" rx=\"1\" transform=\"rotate(90 418 140)\"/><rect class=\"fl\" x=\"414.5\" y=\"123\" width=\"7\" height=\"9\" rx=\"1\" transform=\"rotate(135 418 140)\"/><rect class=\"fl\" x=\"414.5\" y=\"123\" width=\"7\" height=\"9\" rx=\"1\" transform=\"rotate(180 418 140)\"/><rect class=\"fl\" x=\"414.5\" y=\"123\" width=\"7\" height=\"9\" rx=\"1\" transform=\"rotate(225 418 140)\"/><rect class=\"fl\" x=\"414.5\" y=\"123\" width=\"7\" height=\"9\" rx=\"1\" transform=\"rotate(270 418 140)\"/><rect class=\"fl\" x=\"414.5\" y=\"123\" width=\"7\" height=\"9\" rx=\"1\" transform=\"rotate(315 418 140)\"/><circle class=\"ln\" cx=\"418\" cy=\"140\" r=\"11\" fill=\"#fff\"/><circle class=\"ln\" cx=\"418\" cy=\"140\" r=\"4.2\"/></g></g>\n          <text class=\"lb\" x=\"170\" y=\"402\" text-anchor=\"middle\">Follow-Up + CRM</text>\n          <path class=\"ar\" d=\"M170 414 V438 M160 428 l10 10 l10 -10\"/>\n          <g transform=\"translate(-485 345)\"><g transform=\"translate(610 112)\"><circle class=\"ln\" cx=\"0\" cy=\"0\" r=\"7\"/><path class=\"ln\" d=\"M0 7 V30 M-11 16 H11 M0 30 L-8 44 M0 30 L8 44\"/></g><g transform=\"translate(640 112)\"><circle class=\"ln\" cx=\"0\" cy=\"0\" r=\"7\"/><path class=\"ln\" d=\"M0 7 V30 M-11 16 H11 M0 30 L-8 44 M0 30 L8 44\"/></g><g transform=\"translate(670 112)\"><circle class=\"ln\" cx=\"0\" cy=\"0\" r=\"7\"/><path class=\"ln\" d=\"M0 7 V30 M-11 16 H11 M0 30 L-8 44 M0 30 L8 44\"/></g><g transform=\"translate(700 112)\"><circle class=\"ln\" cx=\"0\" cy=\"0\" r=\"7\"/><path class=\"ln\" d=\"M0 7 V30 M-11 16 H11 M0 30 L-8 44 M0 30 L8 44\"/></g></g>\n          <text class=\"lb\" x=\"170\" y=\"530\" text-anchor=\"middle\">Booked Calls</text>\n          <path class=\"ar\" d=\"M170 542 V566 M160 556 l10 10 l10 -10\"/>\n          <text class=\"lb\" x=\"170\" y=\"598\" text-anchor=\"middle\">Clients All Year, Not Just In AEP</text>\n        </svg>\n    </figure>\n    <ol class=\"rail r\">\n      <li><span class=\"n\">01</span><h3>We Handle The Front End</h3><p>The ads, the follow-up, the CRM, all the systems. Leads every month, not just in open enrollment.</p></li>\n      <li><span class=\"n\">02</span><h3>You Close More Of What You Get</h3><p>One sales process across your whole team, so you&rsquo;re getting clients, not just leads.</p></li>\n      <li><span class=\"n\">03</span><h3>We Help You Grow The Team</h3><p>Hiring and training LOAs, so you&rsquo;re not the only one who can close.</p></li>\n      <li><span class=\"n\">04</span><h3>You Make More From Every Client</h3><p>Dental, cancer, hospital, home care. The clients you already paid for are your cheapest leads.</p></li>\n      <li><span class=\"n\">05</span><h3>Then We Turn It Up</h3><p>Once the machine is running: more ad spend, more agents, more production.</p></li>\n    </ol>\n    <div class=\"expect r\">\n      <small>Real Expectations</small>\n      <p>You&rsquo;re probably not going to double your business in 30 days. <b>The goal is leads you can count on, and a team that turns them into clients.</b> Whether you&rsquo;ve run ads before or never have, that&rsquo;s fine.</p>\n    </div>\n    <div class=\"m-cta r\">\n      <a class=\"btn\" href=\"#book\" data-apply>Book A Call With Johnny<i><svg viewBox=\"0 0 16 16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\"><path d=\"M2 8h11M9 4l4 4-4 4\"/></svg></i></a>\n      <p class=\"risk\">On the call we map where you are, where you want to be by the end of the year, and how we&rsquo;d get you there.</p>\n    </div>\n  </div>\n</section>\n\n<!-- 05 WHY AN FMO: the offer no agency can match -->\n<section class=\"why\" data-section=\"why\">\n  <div class=\"wrap\">\n    <h2 class=\"r\">Why No Marketing Agency <em class=\"e\">Can Match This.</em></h2>\n    <p class=\"lead r\">Most FMOs hand you contracts and a comp sheet, and growing is your problem. Most agencies take a retainer and hope. We&rsquo;re built the other way around.</p>\n    <div class=\"vs\">\n      <div class=\"vs-col vs-a r\">\n        <h3>A Marketing Agency Or Lead Vendor</h3>\n        <ul>\n          <li>Charges a big retainer every month, whether it works or not.</li>\n          <li>Sells you leads and walks away. The follow-up is your problem.</li>\n          <li>Hands you off to an account rep.</li>\n        </ul>\n      </div>\n      <div class=\"vs-col vs-b r\">\n        <h3>The Real Insurance Group</h3>\n        <ul>\n          <li><b>We&rsquo;re an FMO. We get paid when you write business,</b> so we&rsquo;re judged on the exact same thing you are.</li>\n          <li><b>We build the front end and the back end,</b> then run it with you for a full year.</li>\n          <li><b>Everything we run, we proved on our own money first.</b> $15,136 in ads, 2,558 leads, $5.92 a lead. In Medicare.</li>\n        </ul>\n        <div class=\"team\">\n          <div class=\"tm\"><img src=\"https://javmartz04-ship-it.github.io/rig-book-a-call-vsl/assets/team-javier.webp\" alt=\"Javier\" loading=\"lazy\"><span><b>Javier</b>CMO, runs the ads</span></div>\n          <div class=\"tm\"><img src=\"https://javmartz04-ship-it.github.io/rig-book-a-call-vsl/assets/team-christopher.webp\" alt=\"Christopher\" loading=\"lazy\"><span><b>Christopher</b>Head Of Systems, builds your back end</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- 06 PROOF: every video testimonial we have -->\n<section class=\"results dark\" data-section=\"results\">\n  <div class=\"wrap\">\n    <div class=\"rs-head\">\n      <div class=\"r\">\n        <p class=\"label\">Real Agents, On Camera</p>\n        <h2>What Happens When Agents <em class=\"e\">Own Their Marketing.</em></h2>\n      </div>\n      <p class=\"lead r\">Agencies stuck on a plateau, agents who were dead outside open enrollment, and agents who had never run an ad. In their own words.</p>\n    </div>\n    <div class=\"ts\">\n      <article class=\"t r\">\n        <div class=\"tv\" data-v=\"https://javmartz04-ship-it.github.io/rig-book-a-call-vsl/assets/video/eugene.mp4\" data-cc=\"https://javmartz04-ship-it.github.io/rig-book-a-call-vsl/assets/video/eugene.vtt\"><img src=\"https://javmartz04-ship-it.github.io/rig-book-a-call-vsl/assets/video/eugene.jpg\" alt=\"Eugene\" loading=\"lazy\"><button type=\"button\" class=\"play\" aria-label=\"Play Eugene's video\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M5 3.5v17a1 1 0 0 0 1.5.86l14-8.5a1 1 0 0 0 0-1.72l-14-8.5A1 1 0 0 0 5 3.5z\"/></svg></button><span class=\"len\">2:38</span></div>\n        <div class=\"tq\">\n          <blockquote>&ldquo;The year prior we barely scratched <span class=\"g\">300 applications</span>. In 2025 I was able to do <span class=\"g\">over 800</span>.&rdquo;</blockquote>\n          <p>&ldquo;I&rsquo;ve been doing it for over 10 years and it seemed like I just hit a plateau. He was able to actually help me grow the book. He&rsquo;ll help you hire people.&rdquo;</p>\n          <cite><b>Eugene</b>Agency owner, 10+ years in Medicare</cite>\n        </div>\n      </article>\n      <article class=\"t r\">\n        <div class=\"tv\" data-v=\"https://javmartz04-ship-it.github.io/rig-book-a-call-vsl/assets/video/mindy.mp4\" data-cc=\"https://javmartz04-ship-it.github.io/rig-book-a-call-vsl/assets/video/mindy.vtt\"><img src=\"https://javmartz04-ship-it.github.io/rig-book-a-call-vsl/assets/video/mindy.jpg\" alt=\"Mindy Baron\" loading=\"lazy\"><button type=\"button\" class=\"play\" aria-label=\"Play Mindy's video\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M5 3.5v17a1 1 0 0 0 1.5.86l14-8.5a1 1 0 0 0 0-1.72l-14-8.5A1 1 0 0 0 5 3.5z\"/></svg></button><span class=\"len\">1:50</span></div>\n        <div class=\"tq\">\n          <blockquote>&ldquo;I have a <span class=\"g\">full calendar outside of open enrollment</span>, which never happened before.&rdquo;</blockquote>\n          <p>&ldquo;Fast forward to today, I&rsquo;m working Facebook, running Facebook ads, and I&rsquo;ve added a virtual assistant.&rdquo;</p>\n          <cite><b>Mindy Baron</b>Agent, 10+ years in insurance</cite>\n        </div>\n      </article>\n      <article class=\"t r\">\n        <div class=\"tv\" data-v=\"https://javmartz04-ship-it.github.io/rig-book-a-call-vsl/assets/video/luke.mp4\" data-cc=\"https://javmartz04-ship-it.github.io/rig-book-a-call-vsl/assets/video/luke.vtt\"><img src=\"https://javmartz04-ship-it.github.io/rig-book-a-call-vsl/assets/video/luke.jpg\" alt=\"Luke Busani\" loading=\"lazy\"><button type=\"button\" class=\"play\" aria-label=\"Play Luke's video\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M5 3.5v17a1 1 0 0 0 1.5.86l14-8.5a1 1 0 0 0 0-1.72l-14-8.5A1 1 0 0 0 5 3.5z\"/></svg></button><span class=\"len\">0:42</span></div>\n        <div class=\"tq\">\n          <blockquote>&ldquo;Being able to have <span class=\"g\">full control over my marketing</span> has really changed my business.&rdquo;</blockquote>\n          <p>&ldquo;I&rsquo;ve been in the industry the last four years, paying for live transfers, direct mail leads, Facebook leads, you name it.&rdquo;</p>\n          <cite><b>Luke Busani</b>Agent, 4 years in Medicare</cite>\n        </div>\n      </article>\n      <article class=\"t r\">\n        <div class=\"tv\" data-v=\"https://javmartz04-ship-it.github.io/rig-book-a-call-vsl/assets/video/franco.mp4\" data-cc=\"https://javmartz04-ship-it.github.io/rig-book-a-call-vsl/assets/video/franco.vtt\"><img src=\"https://javmartz04-ship-it.github.io/rig-book-a-call-vsl/assets/video/franco.jpg\" alt=\"Franco\" loading=\"lazy\"><button type=\"button\" class=\"play\" aria-label=\"Play Franco's video\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M5 3.5v17a1 1 0 0 0 1.5.86l14-8.5a1 1 0 0 0 0-1.72l-14-8.5A1 1 0 0 0 5 3.5z\"/></svg></button><span class=\"len\">1:35</span></div>\n        <div class=\"tq\">\n          <blockquote>&ldquo;I already closed <span class=\"g\">30 deals</span>. It&rsquo;s been two weeks.&rdquo;</blockquote>\n          <p>&ldquo;I&rsquo;ve never done Facebook ads and it&rsquo;s technical. You need help. It&rsquo;s working on our first try.&rdquo;</p>\n          <cite><b>Franco</b>Agent, first Facebook ads ever</cite>\n        </div>\n      </article>\n      <article class=\"t r\">\n        <div class=\"tv\" data-v=\"https://javmartz04-ship-it.github.io/rig-book-a-call-vsl/assets/video/barry.mp4\" data-cc=\"https://javmartz04-ship-it.github.io/rig-book-a-call-vsl/assets/video/barry.vtt\"><img src=\"https://javmartz04-ship-it.github.io/rig-book-a-call-vsl/assets/video/barry.jpg\" alt=\"Barry\" loading=\"lazy\"><button type=\"button\" class=\"play\" aria-label=\"Play Barry&rsquo;s video\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M5 3.5v17a1 1 0 0 0 1.5.86l14-8.5a1 1 0 0 0 0-1.72l-14-8.5A1 1 0 0 0 5 3.5z\"/></svg></button><span class=\"len\">0:55</span></div>\n        <div class=\"tq\">\n          <blockquote>&ldquo;My agency has scaled from doing <span class=\"g\">20 deals a week to 50</span>.&rdquo;</blockquote>\n          <p>&ldquo;Now I have quantity and I have quality. Everything is absolutely running better than it ever has.&rdquo;</p>\n          <cite><b>Barry</b>Agency owner, 7 employees</cite>\n        </div>\n      </article>\n      <article class=\"t r\">\n        <div class=\"tv\" data-v=\"https://javmartz04-ship-it.github.io/rig-book-a-call-vsl/assets/video/justin.mp4\" data-cc=\"https://javmartz04-ship-it.github.io/rig-book-a-call-vsl/assets/video/justin.vtt\"><img src=\"https://javmartz04-ship-it.github.io/rig-book-a-call-vsl/assets/video/justin.jpg\" alt=\"Justin Gray\" loading=\"lazy\"><button type=\"button\" class=\"play\" aria-label=\"Play Justin&rsquo;s video\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M5 3.5v17a1 1 0 0 0 1.5.86l14-8.5a1 1 0 0 0 0-1.72l-14-8.5A1 1 0 0 0 5 3.5z\"/></svg></button><span class=\"len\">0:32</span></div>\n        <div class=\"tq\">\n          <blockquote>&ldquo;We&rsquo;ve come up with how to get ASL leads and they&rsquo;re like <span class=\"g\">12 bucks</span>.&rdquo;</blockquote>\n          <p>&ldquo;My dad&rsquo;s deaf and I know sign language. I&rsquo;m gonna crush all AEP because of it.&rdquo;</p>\n          <cite><b>Justin Gray</b>Medicare agent, ASL market</cite>\n        </div>\n      </article>\n      <article class=\"t r\">\n        <div class=\"tv\" data-v=\"https://javmartz04-ship-it.github.io/rig-book-a-call-vsl/assets/video/taggart.mp4\" data-cc=\"https://javmartz04-ship-it.github.io/rig-book-a-call-vsl/assets/video/taggart.vtt\"><img src=\"https://javmartz04-ship-it.github.io/rig-book-a-call-vsl/assets/video/taggart.jpg\" alt=\"Taggart Allen\" loading=\"lazy\"><button type=\"button\" class=\"play\" aria-label=\"Play Taggart&rsquo;s video\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M5 3.5v17a1 1 0 0 0 1.5.86l14-8.5a1 1 0 0 0 0-1.72l-14-8.5A1 1 0 0 0 5 3.5z\"/></svg></button><span class=\"len\">0:35</span></div>\n        <div class=\"tq\">\n          <blockquote>&ldquo;Johnny showed up <span class=\"g\">every single day</span> and trained me consistently.&rdquo;</blockquote>\n          <p>&ldquo;I&rsquo;m pretty new in the Medicare space. He made sure I understood everything about all different plans.&rdquo;</p>\n          <cite><b>Taggart Allen</b>Medicare agent, new to the industry</cite>\n        </div>\n      </article>\n      <article class=\"t r\">\n        <div class=\"tv\" data-v=\"https://javmartz04-ship-it.github.io/rig-book-a-call-vsl/assets/video/cameron.mp4\" data-cc=\"https://javmartz04-ship-it.github.io/rig-book-a-call-vsl/assets/video/cameron.vtt\"><img src=\"https://javmartz04-ship-it.github.io/rig-book-a-call-vsl/assets/video/cameron.jpg\" alt=\"Cameron De La Pena\" loading=\"lazy\"><button type=\"button\" class=\"play\" aria-label=\"Play Cameron&rsquo;s video\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M5 3.5v17a1 1 0 0 0 1.5.86l14-8.5a1 1 0 0 0 0-1.72l-14-8.5A1 1 0 0 0 5 3.5z\"/></svg></button><span class=\"len\">0:34</span></div>\n        <div class=\"tq\">\n          <blockquote>&ldquo;Johnny has really helped me understand <span class=\"g\">the marketing side</span> of things.&rdquo;</blockquote>\n          <p>&ldquo;That&rsquo;s how we&rsquo;ve got to where we&rsquo;ve got in our business, just kind of replicating what they&rsquo;ve done.&rdquo;</p>\n          <cite><b>Cameron De La Pena</b>Medicare agent</cite>\n        </div>\n      </article>\n      <article class=\"t r wide\">\n        <div class=\"tv\" data-v=\"https://javmartz04-ship-it.github.io/rig-book-a-call-vsl/assets/video/brandon.mp4\" data-cc=\"https://javmartz04-ship-it.github.io/rig-book-a-call-vsl/assets/video/brandon.vtt\"><img src=\"https://javmartz04-ship-it.github.io/rig-book-a-call-vsl/assets/video/brandon.jpg\" alt=\"Brandon De La Pena\" loading=\"lazy\"><button type=\"button\" class=\"play\" aria-label=\"Play Brandon&rsquo;s video\"><svg viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M5 3.5v17a1 1 0 0 0 1.5.86l14-8.5a1 1 0 0 0 0-1.72l-14-8.5A1 1 0 0 0 5 3.5z\"/></svg></button><span class=\"len\">2:26</span></div>\n        <div class=\"tq\">\n          <blockquote>&ldquo;They have <span class=\"g\">every tool you need to grow your agency</span>, whether you&rsquo;re a solo agent or an agency owner.&rdquo;</blockquote>\n          <p>&ldquo;Everyone can have good marketing, but if you don&rsquo;t know the sales process, the back end, the automations, the systems, they can do it all.&rdquo;</p>\n          <cite><b>Brandon De La Pena</b>Agency owner</cite>\n        </div>\n      </article>\n    </div>\n\n  </div>\n</section>\n\n<!-- 07 HOST -->\n<section class=\"host\" data-section=\"host\">\n  <div class=\"wrap h-grid\">\n    <div class=\"h-photo r\"><img src=\"https://javmartz04-ship-it.github.io/rig-book-a-call-vsl/assets/johnny-steeple-color.webp\" width=\"1544\" height=\"1398\" alt=\"Johnny Brock, founder of The Real Insurance Group\" loading=\"lazy\"></div>\n    <div class=\"r\">\n      <p class=\"label\">Meet Johnny Brock</p>\n      <h2>He Was The Top Producer. <em class=\"e\">Then He Learned Marketing.</em></h2>\n      <p class=\"lead\">Johnny came up under his brother, inside a hundred million dollar agency, and was the top producer there. Selling was never the hard part. Getting the leads, and a team to handle them, was.</p>\n      <p class=\"lead\">So he went and learned marketing, and paid eighteen thousand dollars to do it. Sales gets you paid. Marketing gets you scale. Now his team builds that machine for agents, and you work with Johnny directly, not an account rep.</p>\n      <ul class=\"ticks\">\n        <li>Top producer inside a $100M agency</li>\n        <li>Seven years selling Medicare, over 4,000 policies</li>\n        <li>Up to $500K in agent ad spend managed right now</li>\n      </ul>\n    </div>\n  </div>\n</section>\n\n<!-- 08 QUALIFICATION, two-sided -->\n<section class=\"qualify ivory\" data-section=\"qualify\">\n  <div class=\"wrap\">\n    <h2 class=\"r\">This Is For Agents <em class=\"e\">Who Are Already Producing.</em></h2>\n    <div class=\"q-grid\">\n      <div class=\"qc yes r\">\n        <h3>This Is For You If</h3>\n        <ul>\n          <li>You&rsquo;re doing $100K a year and want to get to $250K and past it.</li>\n          <li>You run an agency and want one sales process across your team.</li>\n          <li>You could take on way more clients than you have right now.</li>\n          <li>You&rsquo;ve run ads before, or you never have. Either is fine.</li>\n        </ul>\n      </div>\n      <div class=\"qc no r\">\n        <h3>This Is Not For You If</h3>\n        <ul>\n          <li>You&rsquo;re just looking for cheap leads.</li>\n          <li>You won&rsquo;t follow up with the leads we send.</li>\n          <li>You&rsquo;re not producing yet.</li>\n          <li>You need to double your business in 30 days.</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- 09 CLOSE, footer folded in -->\n<section class=\"close dark\" id=\"book\" data-section=\"close\">\n  <div class=\"wrap\">\n    <p class=\"label r\" style=\"justify-content:center\">The January Cohort</p>\n    <h2 class=\"r\">Thirty Agents. <em class=\"e\"><span data-left>13</span> Seats Left.</em></h2>\n    <p class=\"lead r\">My team builds every Marketing Machine by hand, so each cohort is capped at <span data-total>30</span> agents. Applications for January close <span data-close-long>December 15</span>.</p>\n    <div class=\"cohort r\">\n      <div class=\"c-top\">\n        <div><p class=\"ck\">Cohort</p><p class=\"cv\">January 2027</p></div>\n        <div><p class=\"ck\"><i class=\"dot\" aria-hidden=\"true\"></i>Seats</p><p class=\"cv\"><em data-left>13</em> of <span data-total>30</span> left</p></div>\n        <div><p class=\"ck\">Applications Close</p><p class=\"cv\" data-close-long>December 15</p></div>\n      </div>\n      <div class=\"c-bot\">\n        <div class=\"cd\" id=\"cd\" role=\"timer\" aria-live=\"off\"><p class=\"ck\">Closes In</p><div><b data-cd=\"d\">--</b><small>Days</small></div><div><b data-cd=\"h\">--</b><small>Hrs</small></div><div><b data-cd=\"m\">--</b><small>Min</small></div><div><b data-cd=\"s\">--</b><small>Sec</small></div></div>\n        <p class=\"cdate\" id=\"cdate\" hidden></p>\n        <p class=\"legend\"><span><i></i>Taken</span><span><i class=\"open\"></i>Open</span></p>\n      </div>\n      <div class=\"seats\" id=\"seats\" aria-hidden=\"true\"></div>\n    </div>\n    <div class=\"cta r\">\n      <a class=\"btn\" href=\"#book\" data-apply>Book A Call With Johnny<i><svg viewBox=\"0 0 16 16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\"><path d=\"M2 8h11M9 4l4 4-4 4\"/></svg></i></a>\n      <p class=\"risk\">One on one with Johnny. You leave with a plan, whether we work together or not.</p>\n    </div>\n  </div>\n  <footer class=\"foot\">\n    <div class=\"wrap\">\n      <img src=\"https://javmartz04-ship-it.github.io/rig-book-a-call-vsl/assets/rig-logo-nav.webp\" width=\"392\" height=\"208\" alt=\"The Real Insurance Group\">\n      <div>\n        <p>For licensed insurance professionals only. Not connected with or endorsed by the U.S. government or the federal Medicare program. Individual results vary.</p>\n        <p>&copy; 2026 The Real Insurance Group</p>\n      </div>\n    </div>\n  </footer>\n</section>\n</main>\n\n<!-- survey pop-up: every CTA opens it, then the calendar -->\n<div id=\"sv\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Book A Call With Johnny\" inert>\n  <div class=\"scrim\"></div>\n  <div class=\"mcard\" id=\"svCard\">\n    <div class=\"sv-bar\"><i id=\"svFill\"></i></div>\n    <div class=\"sv-top\"><button type=\"button\" class=\"sv-x\" id=\"svX\" aria-label=\"Close\"><svg viewBox=\"0 0 16 16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"><path d=\"M3 3l10 10M13 3L3 13\"/></svg></button></div>\n    <div class=\"stage\" id=\"svStage\" aria-live=\"polite\"></div>\n  </div>\n</div>\n\n\n\n\n\n", SCRIPTS = [{"src": "https://javmartz04-ship-it.github.io/brandridge-tracker/t.js", "attrs": {"data-client": "johnny", "data-name": "Johnny", "data-funnel": "Book A Call Photo"}, "async": true}, {"src": "https://javmartz04-ship-it.github.io/rig-playbook-optin/ghl/meta.js", "attrs": {"data-funnel": "call"}, "async": true}, {"code": "\ndocument.documentElement.classList.add('js');\n(function () {\n  /* ---- CONFIG ---- */\n  /* ---- COHORT: keep these numbers true. Update SEATS_LEFT as agents sign. ---- */\n  var COHORT = { total: 30, left: 13, close: '2026-12-15T23:59:59-06:00', closeShort: 'Dec 15', closeLong: 'December 15' };\n  (function () {\n    function all(q){ return document.querySelectorAll(q); }\n    all('[data-left]').forEach(function (e) { e.textContent = COHORT.left; });\n    all('[data-total]').forEach(function (e) { e.textContent = COHORT.total; });\n    all('[data-close]').forEach(function (e) { e.textContent = COHORT.closeShort; });\n    all('[data-close-long]').forEach(function (e) { e.textContent = COHORT.closeLong; });\n    var mt = document.getElementById('meter');\n    if (mt) { var mh = ''; for (var q = 0; q < COHORT.total; q++) mh += q < COHORT.total - COHORT.left ? '<i></i>' : '<i class=\"open\"></i>'; mt.innerHTML = mh; }\n    var g = document.getElementById('seats');\n    if (g) {\n      var taken = COHORT.total - COHORT.left, h = '';\n      for (var k = 0; k < COHORT.total; k++) h += k < taken ? '<i></i>' : '<i class=\"open\" style=\"transition-delay:' + ((k - taken) * 60) + 'ms\"></i>';\n      g.innerHTML = h;\n      if ('IntersectionObserver' in window) { var io = new IntersectionObserver(function (es) { es.forEach(function (x) { if (x.isIntersecting) { g.classList.add('in'); io.disconnect(); } }); }, { threshold: .4 }); io.observe(g); } else g.classList.add('in');\n    }\n    var end = new Date(COHORT.close).getTime(), cd = document.getElementById('cd');\n    function pad(n){ return (n < 10 ? '0' : '') + n; }\n    function tick() {\n      var t = Math.max(0, end - Date.now());\n      if (!cd) return;\n      if (t === 0) { cd.style.display = 'none'; var c = document.getElementById('cdate'); if (c) { c.hidden = false; c.textContent = 'Applications for January are closed. Book a call to get on the list for the next cohort.'; } var w = document.querySelector('[data-cohort-pill] .when'); if (w) w.textContent = 'Closed'; return; }\n      var d = Math.floor(t / 864e5), hh = Math.floor(t / 36e5) % 24, mm = Math.floor(t / 6e4) % 60, ss = Math.floor(t / 1e3) % 60;\n      cd.querySelector('[data-cd=\"d\"]').textContent = d; cd.querySelector('[data-cd=\"h\"]').textContent = pad(hh);\n      cd.querySelector('[data-cd=\"m\"]').textContent = pad(mm); cd.querySelector('[data-cd=\"s\"]').textContent = pad(ss);\n      setTimeout(tick, 1000);\n    }\n    tick();\n  })();\n\n  var reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;\n\n  // hero line reveal\n  requestAnimationFrame(function () { requestAnimationFrame(function () { document.getElementById('hero').classList.add('go'); }); });\n\n  // scroll reveals + chart draw\n  document.querySelectorAll('.chart path.draw').forEach(function (p) { p.style.setProperty('--len', Math.ceil(p.getTotalLength())); });\n  var io = new IntersectionObserver(function (es) {\n    es.forEach(function (e) { if (e.isIntersecting) { e.target.classList.add('in'); io.unobserve(e.target); } });\n  }, { rootMargin: '0px 0px -10% 0px', threshold: .08 });\n  document.querySelectorAll('.room .ring').forEach(function (p) { p.style.setProperty('--len', Math.ceil(p.getTotalLength())); });\n  document.querySelectorAll('.r,.chart').forEach(function (el) { io.observe(el); });\n\n  // testimonial videos: poster until tapped, one plays at a time\n  var playing = null;\n  document.querySelectorAll('.tv').forEach(function (tv) {\n    tv.querySelector('.play').addEventListener('click', function () {\n      var v = tv.querySelector('video');\n      if (!v) {\n        v = document.createElement('video');\n        v.src = tv.dataset.v; v.controls = true; v.playsInline = true; v.preload = 'auto'; v.setAttribute('playsinline', '');\n        v.poster = tv.querySelector('img').src;\n        var t = document.createElement('track'); t.kind = 'captions'; t.label = 'English'; t.srclang = 'en'; t.src = tv.dataset.cc; v.appendChild(t);\n        tv.insertBefore(v, tv.firstChild);\n        v.addEventListener('play', function () { if (playing && playing !== v) playing.pause(); if (vid && vid.dataset.live) vid.pause(); playing = v; });\n      }\n      tv.classList.add('on'); v.play().catch(function () {});\n    });\n  });\n})();\n"}, {"code": "window.RIG_SOURCE = 'photo_book_a_call';"}, {"code": "window.BOOK_URL = '/consultation';"}, {"src": "https://javmartz04-ship-it.github.io/rig-book-a-call-vsl/survey.js?v=1794875510", "attrs": {}, "async": false}], TITLE = "Medicare Agents: More Leads Every Month | The Real Insurance Group";
  var d = document;
  d.title = TITLE;
  if (!d.querySelector('meta[name=viewport]')) { var m = d.createElement('meta'); m.name = 'viewport'; m.content = 'width=device-width,initial-scale=1'; d.head.appendChild(m); }
